+TEST_CASE("resume with GPR block-load: x1..x31 via PB ld-sweep, base x31 seeded "
+          "with the scratch GPA and loaded last")
+{
+  RecordingBus bus;
+  bus.dmstatus_value = (1u << 9) | (1u << 17);  // halted + resumeack
+  bus.abstractcs_value = 8u << 24;              // progbufsize = 8 (this DM)
+
+  auto s = rv64_state(0x80001000, 0);
+  for (uint16_t i = 1; i < 32; ++i)
+    s.gpr[i] = 0xB0000000ULL + i;
+  s.vlenb = 64;  // leaves room for the GPR block beside the V region
+
+  hybrid::ResumeDriver driver(bus, kScratch);
+  driver.set_gpr_block_load(true);
+  driver.resume(s);
+
+  auto in_progbuf = [&](uint32_t insn) {
+    for (const auto& op : bus.ops)
+      if (op.kind == DmiOp::Kind::Write && op.reg >= hybrid::kProgbuf0
+          && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
+          && op.value == insn)
+        return true;
+    return false;
+  };
+
+  // (a) x1..x31 are all reloaded via ld in the Program Buffer -- x31 too, now
+  //     that the memory-decoder fix makes its final-word slot readable. x31 is
+  //     the base pointer, so its own ld is the last one executed.
+  int found = 0;
+  for (uint8_t k = 1; k < 32; ++k)
+    if (in_progbuf(hybrid::encode_ld(k, 31, static_cast<int32_t>((k - 1) * 8))))
+      ++found;
+  CHECK(found == 31);
+  CHECK(in_progbuf(hybrid::encode_ld(31, 31, 30 * 8)));  // x31 rides the sweep
+
+  // (b) exactly ONE GPR abstract write to x31: it seeds the base pointer with
+  //     the scratch GPA. x31's architectural value now arrives via its own ld
+  //     (last in the sweep), so there is no second abstract write. No other GPR
+  //     uses an abstract write (x1..x31 all come via ld).
+  const uint64_t gpr_gpa = hybrid::gpr_scratch_gpa(kScratch);
+  std::vector<uint64_t> x31_writes;
+  int nonx31_gpr_writes = 0;
+  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
+    const auto& op = bus.ops[i];
+    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
+    const uint16_t rn = static_cast<uint16_t>(op.value & 0xFFFFu);
+    if (!((op.value >> 16) & 1u)) continue;
+    if (rn == hybrid::regno_gpr(31))
+      x31_writes.push_back((uint64_t(bus.ops[i - 1].value) << 32)
+                           | bus.ops[i - 2].value);
+    else if (rn > hybrid::regno_gpr(0) && rn <= hybrid::regno_gpr(30))
+      ++nonx31_gpr_writes;
+  }
+  REQUIRE(x31_writes.size() == 1u);
+  CHECK(x31_writes.front() == gpr_gpa);            // base seed only
+  CHECK(nonx31_gpr_writes == 0);
+
+  // (c) with progbufsize=8 (7 loads/execution) the 31 loads take 5 Program-
+  //     Buffer executions (7+7+7+7+3), not 31 abstract writes.
+  int execs = 0;
+  for (const auto& op : bus.ops)
+    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
+        && op.value == hybrid::kExecProgbufCmd)
