  void request_resume()
  {
    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
  }

  void write_64bit_register(uint16_t regno, uint64_t value)
  {
    write_register_abstract(bus_, regno, value);
  }

  // GPR block-load: seed x31 with the scratch GPA (the base pointer), then ld
  // x1..x31 from their slots via the Program Buffer. So 31 registers cost one
  // abstract write + a few PB executions instead of 31 abstract writes. `ld`'s
  // 12-bit offset spans every slot (<= 240). x31 is the base, so its own ld is
  // emitted LAST: it may clobber the base only after every other load has used
  // it. (x31's slot is the mapping's final word, which the memory decoder now
  // returns correctly.)
  void restore_gprs_via_pb(uint64_t gpr_gpa)
  {
    // The Program Buffer holds abstractcs.progbufsize entries (this DM reports
    // 8); reserve one slot for the terminating ebreak, so at most
    // progbufsize-1 loads per execution. x31 stays the base through every load
    // except its own (emitted last), so batches compose freely.
    const uint32_t progbufsize = (bus_.read(kAbstractcs) >> 24) & 0x1Fu;
    const std::size_t max_lds = (progbufsize > 1) ? progbufsize - 1u : 1u;
    write_register_abstract(bus_, regno_gpr(31), gpr_gpa);  // base pointer
    std::array<uint32_t, 32> batch{};
    std::size_t n = 0;
    for (uint8_t k = 1; k < 32; ++k) {  // x1..x31; x31 (the base) loaded last
      batch[n++] = encode_ld(k, 31, static_cast<int32_t>((k - 1) * 8));
      if (n == max_lds || k == 31) {
        exec_progbuf(bus_, std::span<const uint32_t>{batch.data(), n});
        n = 0;
      }
    }
  }

  // Abstract-first CSR write with Program Buffer fallback.
  // Tries an abstract register write; if the DM signals cmderr, clears it,
  // stages the value in scratch_gpr via abstract GPR write, then executes a
  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
  // to x5 (t0) which the GPR restore loop overwrites later.
  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
                                 uint8_t scratch_gpr = 5)
  {
    write_64bit_register(regno_csr(csr), value);
    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
    write_64bit_register(regno_gpr(scratch_gpr), value);
